import csv
import io
from money import format_total

def render_order(order):
    out = io.StringIO()
    writer = csv.writer(out)
    writer.writerow(["id", "total"])
    writer.writerow([order["id"], format_total(order["total"])])
    return out.getvalue()
def format_total(amount):
    return f"{amount:.2f}"
